import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { uv, vec3, mix, screenUV } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const aspect = 512 / 320;
  const width = 2.4;
  const height = width / aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial();

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const accentColor = new Color(colors.accent);

  material.colorNode = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    uv().y
  );

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/orb-decor.png';
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      material.colorNode = mix(
        material.colorNode,
        texture.toVar(),
        texture.a
      );
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load image texture for journal card 1:', err);
    });
  }

  // Border accent line
  const borderGeom = new PlaneGeometry(width + 0.04, height + 0.04);
  const borderMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.15
  });
  const borderMesh = new Mesh(borderGeom, borderMat);
  borderMesh.position.z = -0.01;
  group.add(borderMesh);

  // Content population (if any text is provided in config)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textY = height / 2 - 0.2;
  const textGroup = new Group();
  textGroup.position.z = 0.01;
  group.add(textGroup);

  for (const item of textItems) {
    const isHeader = item.role === 'heading' || item.role === 'title';
    const textElement = ctx.fontAtlas.createText(item.text, {
      fontSize: isHeader ? 32 : 18,
      color: isHeader ? colors.paper : colors.accent,
      align: 'left',
      maxWidthPx: 400
    });
    textElement.position.set(-width / 2 + 0.15, textY, 0);
    textGroup.add(textElement);
    textY -= isHeader ? 0.25 : 0.15;
  }

  // Clean implementation. No interactive behaviors for static layout
  const timelines = [];

  // Rise-in animation
  const tl = gsap.timeline();
  group.position.y -= 0.2;
  group.scale.set(0.95, 0.95, 0.95);
  tl.to(group.position, { y: '+=0.2', duration: 0.8, ease: 'power3.out' });
  tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.8, ease: 'power3.out' }, '<');
  timelines.push(tl);

  // Apply cinematic primitives (none expected for this asset but dynamic handling is safe)
  const primitivesConfig = config.cinematicPrimitives ?? [];
  const activePrimitives = [];
  primitivesConfig.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      const res = ctx.primitives[prim.name](group, prim.params);
      if (res) activePrimitives.push(res);
    }
  });

  group.userData = {
    handlers: {},
    cleanup: () => {
      timelines.forEach((t) => t.kill());
      activePrimitives.forEach((p) => {
        if (p.cleanup) p.cleanup();
      });
      geometry.dispose();
      material.dispose();
      borderGeom.dispose();
      borderMat.dispose();
    }
  };

  return group;
}
